insert into org.circulo (numero, nome, sigla, prefixo, descricao, principio, situacao) select numero, nome, sigla, prefixo, descricao, principio, situacao from jsonb_to_recordset($j$[{"numero": 1, "nome": "Identidade", "sigla": "ID", "prefixo": "ID", "descricao": "A Identidade padroniza, normatiza e sistematiza. Quem executa são os outros círculos, e quem audita é a Governança. São cinco jornadas: declarar quem somos, transformar isso em regra, criar as marcas, definir o posicionamento e avaliar se os padrões funcionam. O Soul Brand é a declaração de identidade em vigor: é a saída da ID-01 e serve de insumo às outras quatro.", "principio": null, "situacao": "Fechado em 01/10/2026 · mudanças aprovadas aplicadas em 02/10/2026 · proposta da revisão aplicada em 03/10/2026 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 2, "nome": "Estratégia", "sigla": "ES", "prefixo": "ES", "descricao": "A Estratégia faz o trabalho de estratégia de ponta a ponta: formula, propõe, desdobra em alvos, decide os portões dentro da alçada e acompanha as hipóteses. Na formulação, o executivo e o líder do círculo propõem e participam, mas não decidem. Os sócios aprovam. A Gestão opera a rotina: orçamento e ritual de acompanhamento. A Integração é o PMO corporativo e coordena projetos, implantações e lançamentos. São seis jornadas.", "principio": null, "situacao": "Fechado em 01/10/2026 · todas as mudanças aprovadas aplicadas em 02/10/2026 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 3, "nome": "Inteligência", "sigla": "IN", "prefixo": "IN", "descricao": "A Inteligência sabe antes e melhor e transforma o que sabe em oferta. Lê o mercado, responde a quem decide, torna o dado confiável, mede os indicadores, cura as bases de conhecimento, escreve os métodos e desenha as ofertas. Decide o que é do seu ofício (a medida, o método e a curadoria) e, entre os dois portões, a oferta, ouvidos o executivo, Negócios e a Gestão. Não decide o portfólio nem a regra, não monta nem opera agentes e não responde pelo resultado que mede. São oito jornadas.", "principio": null, "situacao": "Fechado em 02/10/2026 · propostas do círculo 4 aplicadas · auditoria de execução aplicada em 03/10/2026"}, {"numero": 4, "nome": "Relações", "sigla": "RE", "prefixo": "RE", "descricao": "Relações constrói e cuida das relações com o mercado, os clientes, os parceiros e as instituições, antes e depois do contrato. Gera demanda e entrega a Negócios oportunidades qualificadas, desenha a experiência do cliente, acompanha o sucesso de cada cliente, forma parcerias, comunica para fora e vigia a reputação. Não vende, não atende, não define a marca e não decide a crise. São oito jornadas.", "principio": "Regra do círculo, aprovada às 19:05: Relações decide o que é do seu ofício (o plano de demanda, a qualificação das oportunidades, a estratégia de experiência do cliente, a pauta e o conteúdo externo e as parcerias dentro da alçada), ouvidos o executivo da empresa e Negócios. O executivo aprova o que se diz em nome da empresa e quem fala por ela. Negócios vende e renova; Operações atende e entrega; a Identidade dá a marca e os padrões; a Governança conduz o comitê de crise, e o dono da crise decide; a Governança cuida dos contratos e das regras de dados pessoais.", "situacao": "Fechado em 02/10/2026 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 5, "nome": "Negócios", "sigla": "NE", "prefixo": "NE", "descricao": "Negócios transforma oportunidade em contrato e cuida dos contratos dos clientes. Mantém a tabela de preços e a política comercial, planeja as vendas e prevê a receita, faz a proposta, negocia e fecha o contrato, disputa licitações, renova, amplia, adita e encerra contratos e vende com parceiros e em oferta conjunta entre as empresas. Não gera demanda, não desenha a oferta, não implanta, não entrega e não fatura. São sete jornadas.", "principio": "Regra do círculo, aprovada às 20:11: Negócios decide o que é do seu ofício (o aceite da oportunidade, o escopo e a proposta dentro do catálogo, a tabela de preços e a política comercial, a concessão dentro da alçada de quem vende e a participação em licitação), ouvido o executivo da empresa. O executivo aprova a concessão acima da alçada de quem vende e assina pela empresa; acima da alçada dele, decidem os sócios; a faixa de desconto de quem vende é aprovada pela Governança. Relações gera e qualifica a demanda e acompanha o cliente; a Inteligência desenha a oferta e o preço-base; a Integração implanta; Operações entrega; a Gestão fatura; a Governança mantém os modelos e as alçadas e revisa e guarda os contratos.", "situacao": "Fechado em 02/10/2026 · proposta do círculo 6 aplicada em 03/10/2026 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 6, "nome": "Integração", "sigla": "IT", "prefixo": "IT", "descricao": "A Integração faz o todo funcionar como um só. É o escritório de projetos do Ecossistema: mantém a carteira de projetos, implanta os clientes, coordena o lançamento das ofertas e a saída de ofertas e empresas. Mantém o catálogo de capacidades e as jornadas ponta a ponta, monta, testa, libera e monitora agentes e automações e opera a tecnologia. Não decide o que o agente precisa saber, não roda a entrega recorrente e não define as regras. São oito jornadas.", "principio": "Regra do círculo, aprovada às 09:30 de 03/10/2026: a Integração decide o que é do seu ofício (o método de projetos, a arquitetura e a plataforma, a ficha técnica de cada capacidade, a liberação do agente pelos casos de teste e a mudança em sistemas), ouvidos os donos. O executivo decide a prioridade dos projetos da sua empresa, como diz o documento-base; o líder do círculo dono decide o redesenho da jornada do seu círculo e aceita a capacidade e o agente; a Inteligência diz o que o agente precisa saber e mede se ele acertou; a Governança define a alçada, confere a segurança e audita.", "situacao": "Fechado em 03/10/2026 · propostas dos círculos 7 e 9 aplicadas em 03/10/2026 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 7, "nome": "Operações", "sigla": "OP", "prefixo": "OP", "descricao": "Operações cumpre a promessa feita ao cliente. Planeja a capacidade de entrega, assume cada cliente implantado e roda a entrega recorrente, atende pedidos e problemas, trata reclamações, garante a qualidade e os níveis de serviço e encerra as entregas no fim do contrato ou na saída. Onde há produto físico, cuida da cadeia de suprimentos e do pós-venda. Não muda o desenho, não compra e não fatura. São oito jornadas.", "principio": "Regra do círculo, aprovada por você às 11:50 de 03/10/2026: Operações decide o que é do seu ofício (o plano de capacidade, o plano de entrega de cada cliente, os procedimentos e os níveis de serviço, a solução da reclamação dentro da alçada e a ação corretiva). O executivo decide o que passa da alçada de Operações e o recall; Relações define os padrões de experiência; a Integração muda jornadas, sistemas e agentes; a Gestão compra e fatura; a Governança define a alçada e avalia o dever de comunicar a autoridade.", "situacao": "Fechado em 03/10/2026, aprovado às 11:50 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 8, "nome": "Gestão", "sigla": "GE", "prefixo": "GE", "descricao": "A Gestão garante os recursos e a rotina. Desdobra e controla o orçamento aprovado, roda o ritual de acompanhamento dos alvos, fatura e recebe, compra e paga, fecha as contas e os impostos, aplica o rateio entre as empresas e cuida das pessoas: provê, integra à cultura, avalia, desenvolve, paga, reconhece e comunica para dentro. Cuida também dos ativos. Não define as regras nem escolhe o rumo. São treze jornadas.", "principio": "Regra do círculo, aprovada por você às 11:50 de 03/10/2026: a Gestão decide o que é do seu ofício (o desdobramento e o controle do orçamento aprovado, o ritual de acompanhamento, a cobrança, a compra, o fechamento das contas, a aplicação do rateio e os processos de pessoas), dentro da alçada. Os sócios aprovam alvos e orçamento; o executivo decide o que passa da alçada da Gestão; o líder decide a contratação na sua equipe; o desligamento é decidido pelo executivo, com o líder; a Governança define as alçadas, o critério de rateio e as regras e guarda os contratos.", "situacao": "Fechado em 03/10/2026, aprovado às 11:50 · auditoria de execução aplicada em 03/10/2026"}, {"numero": 9, "nome": "Governança", "sigla": "GO", "prefixo": "GO", "descricao": "A Governança faz o Ecossistema decidir bem e dentro das regras. Mantém as regras, as políticas e as alçadas de pessoas e agentes, secretaria as decisões dos sócios, gere riscos, conformidade e controles, mantém as obrigações legais e os contratos em dia, audita as entregas de pessoas e agentes, responde aos titulares de dados, conduz o comitê de crise, recebe relatos, comunica às autoridades e publica o relato de impacto. Não executa a rotina nem escolhe o rumo. São dez jornadas.", "principio": "Regra do círculo, aprovada por você às 11:50 de 03/10/2026: a Governança decide o que é do seu ofício (a redação e a publicação das regras, a revisão jurídica, a guarda dos contratos, a amostra e o julgamento da auditoria, a resposta ao titular de dados e a comunicação à autoridade), dentro da alçada. Os sócios decidem as regras gerais, as alçadas dos executivos e o que a lei reserva a eles; o dono da crise (executivo, Administrador do IMTS.OS ou sócios) decide a crise, com o comitê conduzido pela Governança; os círculos donos executam e corrigem.", "situacao": "Fechado em 03/10/2026, aprovado às 11:50 · auditoria de execução aplicada em 03/10/2026"}]$j$::jsonb) as x(numero smallint, nome text, sigla text, prefixo text, descricao text, principio text, situacao text);
